            return $this->ref;
        }
        throw new Exception('never get to getRef Items::ref');
    }

    /**
     * @return string
     */
    public static function sampleRef(): string {
        return 'Items::ref::31'; /*31:ref*/
    }

    /**
     * @throws Exception
     * @return bool
     */
    public function validate(): bool {
        return Items::validateRef($this->ref);
    }

    /**
     * @return stdClass
     * @throws Exception
     */
    public function to(): stdClass  {
        $out = new stdClass();
        $out->{'$ref'} = $this->toRef();
        return $out;
    }

    /**
     * @param stdClass $obj
     * @return Items
     * @throws Exception
     */
    public static function from(stdClass $obj): Items {
        if (!property_exists($obj, '$ref')) {
            throw new Exception("Missing required property");
        }
        return new Items(
         Items::fromRef($obj->{'$ref'})
        );
    }

    /**
     * @return Items
     */
    public static function sample(): Items {
        return new Items(
         Items::sampleRef()
        );
    }
}
